head.script:
scwin.vScrenID = "ULDFIS00303.xml";
// 전역 변수 선언
scwin.vKisCd = "";
scwin.vAcntclsDt= "";

scwin.vKisCd     = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();
scwin.vAcntclsDt = $p.parent().wfm_header.getWindow().sbx_AcntclsDt.getValue();

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
   scwin.init();
};

scwin.onpageunload = function() {
};

// 일반 함수
/**
 *  화면 초기화
 */
scwin.init = async function() {
    // 결산일자 조회
     await $p.parent().wfm_header.getWindow().scwin.fn_SrchAcntclsDt();
    //리스회계처리 조회
    //    setTimeout(async function () {
    //       await scwin.fn_Search();
    //    }, 1000) ;

     //await scwin.fn_Search();
};

/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_LeaseAcntgProcsRes.removeAll();
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    if ($p.parent().wfm_header.getWindow().ibx_KisCd.getValue() === "" || $p.parent().wfm_header.getWindow().sbx_AcntclsDt.getValue() === "") {
        return false;
    }
    return true;
};

/**
 * 리스회계처리  조회
 */
scwin.search = async function() {

    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
     if (!scwin.chkValid()) {
         return;
     }
    let ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue() ; 
    let sbxAcntclsDt = $p.parent().wfm_header.getWindow().sbx_AcntclsDt.getValue();

    let url = "/api/listing/nice/individual-notes/lease-accounting?kisCd="+ibxKisCd+"&acntclsDt="+sbxAcntclsDt;
    await $c.sbm.setAction(sbm_dlt_LeaseAcntgProcs, url);
    await $c.sbm.execute(sbm_dlt_LeaseAcntgProcs);

    await scwin.appendContents(); 

};

/**
 * 컨텐츠 append
 */
scwin.appendContents = function() {
    let strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:600px;font-family:돋움체;'>";
    for (let nRow = 0; nRow <= dlt_LeaseAcntgProcsRes.getRowCount(); nRow++) {
        strContent = strContent + dlt_LeaseAcntgProcsRes.getCellData(nRow, "ctnt");
    }
    strContent = strContent + "</div>";
    let grpCtntObj = $p.getComponentById("grp_Ctnt").render;
    grpCtntObj.innerHTML = strContent;
    grp_Ctnt.setStyle("border", "1px solid blue");
    grp_Ctnt.setStyle("magin-top", "30px");

};
